V112_B64 = """"""

def embedded_source(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")

V112_SOURCE = embedded_source(V112_B64)

ROOT = Path(".")
LAB = ROOT / "mfp3_synergy_lab"
LAB.mkdir(exist_ok=True)

YEARLY_CSV = LAB / "synergy_yearly.csv"
PATTERNS_CSV = LAB / "synergy_patterns.csv"
PORTFOLIO_CSV = LAB / "synergy_portfolio.csv"
METRICS_CSV = LAB / "synergy_metrics.csv"
CURRENT_CSV = LAB / "current_synergy_signals.csv"
STATE_JSON = LAB / "synergy_state.json"

TARGETS = ["QQQ", "ECH", "CPER"]
HORIZONS = [1, 5, 20]
FIRST_TEST_YEAR = 2019

MAX_FEATURES = 12
MAX_FINAL_PATTERNS = 8

MIN_YEAR_SUPPORT = 10
MIN_TOTAL_DISCOVERY_SUPPORT = 40
MIN_VALIDATION_SUPPORT = 18

Z_ON_GRID = [0.20, 0.35, 0.50]
FLOORS = [0.0, 0.25, 0.50, 0.67]

ONE_WAY_COST = 0.0015
MAX_ASSET_WEIGHT = 0.30
INITIAL_CAPITAL = 10_000_000.0

RUN_EVERY_DAYS = 21
TASK_NAME = "MFP3_ONEFILE_V113_DAILY"

# ---------------------------------------------------------------------
# Base v1.12
# ---------------------------------------------------------------------

def get_v112_namespace():
    g = {
        "__name__": "mfp3_v112_library",
        "__file__": "<embedded:v1.12>",
        "__builtins__": __builtins__,
    }
    exec(compile(V112_SOURCE, g["__file__"], "exec"), g, g)
    return g

def run_v112(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v112_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v112_embedded",
            "__file__": "<embedded:v1.12>",
            "__builtins__": __builtins__,
        }
        exec(compile(V112_SOURCE, g["__file__"], "exec"), g, g)
        g["main"]()
    finally:
        sys.argv = old

# ---------------------------------------------------------------------
# Scheduler
# ---------------------------------------------------------------------

def install_this_file():
    if os.name != "nt":
        raise SystemExit("--install sólo funciona en Windows.")

    script = str(Path(__file__).resolve())
    python = str(Path(sys.executable).resolve())
    action = f'"{python}" "{script}"'

    p = subprocess.run(
        [
            "schtasks", "/Create",
            "/TN", TASK_NAME,
            "/TR", action,
            "/SC", "DAILY",
            "/ST", "18:30",
            "/F",
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )

    if p.returncode != 0:
        print(p.stdout)
        print(p.stderr)
        raise SystemExit("No se pudo instalar la tarea.")

    print(p.stdout.strip())
    print("Instalado: v1.13 se ejecutará diariamente a las 18:30.")

def uninstall_this_file():
    if os.name != "nt":
        raise SystemExit("--uninstall sólo funciona en Windows.")

    p = subprocess.run(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    print((p.stdout or p.stderr).strip())

# ---------------------------------------------------------------------
# Utilities
# ---------------------------------------------------------------------

def now_utc():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def perf(ret):
    r = pd.Series(ret).fillna(0.0)
    if len(r) == 0:
        return {
            "total_return": 0.0,
            "cagr": 0.0,
            "sharpe": 0.0,
            "max_drawdown": 0.0,
            "ann_vol": 0.0,
        }

    curve = (1 + r).cumprod()
    total = float(curve.iloc[-1] - 1.0)
    years = max(len(r) / 252.0, 1 / 252.0)
    cagr = float(curve.iloc[-1] ** (1.0 / years) - 1.0)
    vol = float(r.std() * np.sqrt(252))
    sharpe = float(r.mean() * 252 / vol) if vol > 1e-12 else 0.0
    dd = curve / curve.cummax() - 1.0

    return {
        "total_return": total,
        "cagr": cagr,
        "sharpe": sharpe,
        "max_drawdown": float(dd.min()),
        "ann_vol": vol,
    }

def weeklyize(pos):
    p = pos.fillna(0.0).clip(0, 1)
    out = pd.Series(index=p.index, dtype=float)
    state = 0.0

    for i, (dt, v) in enumerate(p.items()):
        if i == 0 or i % 5 == 0:
            state = float(v)
        out.loc[dt] = state

    return out

def strategy_returns(position, daily_ret):
    target = weeklyize(position)
    exec_pos = target.shift(1).fillna(0.0)
    held = target.shift(2).fillna(0.0)
    turnover = exec_pos.diff().abs().fillna(exec_pos.abs())
    gross = held * daily_ret.fillna(0.0)
    net = gross - turnover * ONE_WAY_COST
    return net, held, turnover

def utility(ret, turnover):
    p = perf(ret)
    score = (
        p["sharpe"]
        + 0.30 * p["total_return"]
        - 0.60 * abs(p["max_drawdown"])
        - 0.012 * float(turnover.sum())
    )
    return score, p

def enough_year(df, year):
    return int(np.sum(df.index.year == year)) >= 100

def years_df(df, years):
    return df[df.index.year.isin(years)].copy()

def feature_cols(df):
    exclude = {"price_clp", "daily_ret_clp"}
    for h in HORIZONS:
        exclude |= {f"fwd_ret_{h}", f"y_up_{h}"}
    return [c for c in df.columns if c not in exclude]

# ---------------------------------------------------------------------
# Feature stability
# ---------------------------------------------------------------------

def discover_stable_features(df, h, discovery_years):
    rows = []

    for f in feature_cols(df):
        fold = []

        for y in discovery_years:
            z = df[df.index.year == y][[f, f"fwd_ret_{h}"]].dropna()

            if len(z) < 80:
                continue

            ic = z[f].rank().corr(
                z[f"fwd_ret_{h}"].rank()
            )

            if pd.notna(ic):
                fold.append(float(ic))

        if len(fold) < 3:
            continue

        mean_ic = float(np.mean(fold))

        if abs(mean_ic) < 0.008:
            continue

        direction = 1.0 if mean_ic >= 0 else -1.0
        consistent = float(
            np.mean([
                np.sign(x) == np.sign(mean_ic)
                for x in fold if x != 0
            ])
        )

        stability = (
            abs(mean_ic)
            * consistent
            / (1.0 + float(np.std(fold)))
        )

        rows.append({
            "feature": f,
            "mean_ic": mean_ic,
            "direction": direction,
            "consistency": consistent,
            "stability": stability,
        })

    st = pd.DataFrame(rows)

    if st.empty:
        return st

    st = st.sort_values(
        ["consistency", "stability"],
        ascending=False,
    )

    good = st[
        (st["consistency"] >= 2/3)
    ].head(MAX_FEATURES)

    if len(good) < 6:
        good = st.head(MAX_FEATURES)

    return good

# ---------------------------------------------------------------------
# Robust state transform
# ---------------------------------------------------------------------

def scale_fit(discovery, features):
    out = {}

    for f in features:
        s = pd.to_numeric(
            discovery[f], errors="coerce"
        )

        med = float(s.median())
        mad = float((s - med).abs().median())
        scale = 1.4826 * mad

        if not np.isfinite(scale) or scale < 1e-8:
            scale = float(s.std())

        if not np.isfinite(scale) or scale < 1e-8:
            scale = 1.0

        out[f] = (med, scale)

    return out

def state_matrix(z, ft, scale):
    out = pd.DataFrame(index=z.index)

    for r in ft.itertuples():
        med, sd = scale[r.feature]
        raw = (
            pd.to_numeric(
                z[r.feature], errors="coerce"
            ) - med
        ) / sd

        out[r.feature] = raw * float(r.direction)

    return out

# ---------------------------------------------------------------------
# Single signal baseline
# ---------------------------------------------------------------------

def mask_for(states, pattern, z_on):
    m = pd.Series(True, index=states.index)
    for f in pattern:
        m &= states[f] > z_on
    return m

def edge_for_period(frame, states, pattern, h, z_on):
    target = pd.to_numeric(
        frame[f"fwd_ret_{h}"], errors="coerce"
    )

    valid = target.dropna()

    if len(valid) == 0:
        return None

    base_mean = float(valid.mean())
    base_hit = float((valid > 0).mean())

    m = mask_for(
        states, pattern, z_on
    ) & target.notna()

    n = int(m.sum())

    if n == 0:
        return {
            "support": 0,
            "edge": np.nan,
            "hit_edge": np.nan,
            "mean": np.nan,
            "hit": np.nan,
            "base_mean": base_mean,
            "base_hit": base_hit,
        }

    r = target[m]

    return {
        "support": n,
        "edge": float(r.mean()) - base_mean,
        "hit_edge": float((r > 0).mean()) - base_hit,
        "mean": float(r.mean()),
        "hit": float((r > 0).mean()),
        "base_mean": base_mean,
        "base_hit": base_hit,
    }

# ---------------------------------------------------------------------
# Genuine synergy discovery
# ---------------------------------------------------------------------

def discover_synergies(
    df,
    h,
    discovery_years,
    ft,
    states_by_year,
):
    features = ft["feature"].tolist()

    # Singles: only as comparison baseline. They can NEVER become final patterns.
    single_edge = {}

    for f in features:
        per = []

        for y in discovery_years:
            res = edge_for_period(
                df[df.index.year == y],
                states_by_year[y],
                (f,),
                h,
                0.35,
            )
            if res and res["support"] >= MIN_YEAR_SUPPORT:
                per.append(res["edge"])

        single_edge[f] = (
            float(np.mean(per))
            if per else -999.0
        )

    patterns = (
        list(itertools.combinations(features, 2))
        + list(itertools.combinations(features[:9], 3))
    )

    rows = []

    for pat in patterns:
        for z_on in Z_ON_GRID:
            yearly = []
            total_support = 0

            for y in discovery_years:
                res = edge_for_period(
                    df[df.index.year == y],
                    states_by_year[y],
                    pat,
                    h,
                    z_on,
                )

                if (
                    res is None
                    or res["support"] < MIN_YEAR_SUPPORT
                ):
                    continue

                yearly.append(res)
                total_support += res["support"]

            if len(yearly) < 3:
                continue

            edges = np.array([x["edge"] for x in yearly])
            hit_edges = np.array([x["hit_edge"] for x in yearly])

            if total_support < MIN_TOTAL_DISCOVERY_SUPPORT:
                continue

            positive_year_rate = float(
                np.mean(edges > 0)
            )

            if positive_year_rate < 2/3:
                continue

            avg_edge = float(np.mean(edges))
            avg_hit_edge = float(np.mean(hit_edges))

            best_single = max(
                single_edge.get(f, -999.0)
                for f in pat
            )

            synergy_edge = avg_edge - best_single

            # Genuine confluence must beat the best constituent.
            if avg_edge <= 0:
                continue

            if synergy_edge <= 0:
                continue

            # Conservative score: repeated + synergistic + supported.
            score = (
                avg_edge
                * synergy_edge
                * positive_year_rate
                * np.sqrt(total_support)
                * (1.0 + max(-0.15, avg_hit_edge))
            )

            rows.append({
                "pattern": " & ".join(pat),
                "members_json": json.dumps(pat),
                "size": len(pat),
                "z_on": z_on,
                "support_discovery": total_support,
                "positive_year_rate": positive_year_rate,
                "edge_discovery": avg_edge,
                "hit_edge_discovery": avg_hit_edge,
                "best_single_edge": best_single,
                "synergy_edge": synergy_edge,
                "discovery_score": score,
            })

    tab = pd.DataFrame(rows)

    if tab.empty:
        return tab

    return tab.sort_values(
        ["discovery_score", "synergy_edge"],
        ascending=False,
    )

# ---------------------------------------------------------------------
# Two-year validation
# ---------------------------------------------------------------------

def validate_synergies(
    df,
    h,
    validation_years,
    tab,
    states_by_year,
):
    if tab.empty:
        return pd.DataFrame()

    rows = []

    for r in tab.head(60).itertuples(index=False):
        pat = tuple(json.loads(r.members_json))
        folds = []
        support = 0

        for y in validation_years:
            res = edge_for_period(
                df[df.index.year == y],
                states_by_year[y],
                pat,
                h,
                float(r.z_on),
            )

            if (
                res is None
                or res["support"] < MIN_YEAR_SUPPORT
            ):
                continue

            folds.append(res)
            support += res["support"]

        if len(folds) < 2:
            continue

        edges = np.array([x["edge"] for x in folds])
        hit_edges = np.array([x["hit_edge"] for x in folds])

        if support < MIN_VALIDATION_SUPPORT:
            continue

        # Must remain useful over the 2 separate validation years.
        positive_rate = float(np.mean(edges > 0))

        if positive_rate < 0.50:
            continue

        mean_edge = float(np.mean(edges))

        if mean_edge <= 0:
            continue

        worst_edge = float(np.min(edges))
        mean_hit_edge = float(np.mean(hit_edges))

        # Shrinkage to protect against small samples.
        shrink = support / (support + 40.0)
        shrunk = mean_edge * shrink

        # Penalize a strongly negative validation year.
        robustness = (
            shrunk
            - 0.50 * max(0.0, -worst_edge)
        )

        if robustness <= 0:
            continue

        raw_weight = (
            robustness
            * float(r.synergy_edge)
            * np.sqrt(support)
            * (1.0 + max(-0.15, mean_hit_edge))
        )

        rows.append({
            **r._asdict(),
            "support_validation": support,
            "positive_validation_rate": positive_rate,
            "edge_validation": mean_edge,
            "worst_edge_validation": worst_edge,
            "hit_edge_validation": mean_hit_edge,
            "shrunk_edge_validation": shrunk,
            "robustness": robustness,
            "weight_raw": raw_weight,
        })

    vt = pd.DataFrame(rows)

    if vt.empty:
        return vt

    # Diversity filter: don't let near-identical combinations dominate.
    vt = vt.sort_values(
        ["weight_raw", "robustness"],
        ascending=False,
    )

    selected = []
    sets = []

    for r in vt.itertuples(index=False):
        members = set(json.loads(r.members_json))

        too_similar = False
        for prev in sets:
            overlap = (
                len(members & prev)
                / max(1, len(members | prev))
            )
            if overlap >= 0.67:
                too_similar = True
                break

        if too_similar:
            continue

        selected.append(r._asdict())
        sets.append(members)

        if len(selected) >= MAX_FINAL_PATTERNS:
            break

    out = pd.DataFrame(selected)

    if out.empty:
        return out

    total = out["weight_raw"].clip(lower=0).sum()

    if total <= 0:
        return pd.DataFrame()

    out["weight"] = (
        out["weight_raw"].clip(lower=0)
        / total
    )

    return out

# ---------------------------------------------------------------------
# Score
# ---------------------------------------------------------------------

def confluence_score(states, patterns):
    score = pd.Series(0.0, index=states.index)

    if patterns.empty:
        return score

    for r in patterns.itertuples(index=False):
        pat = tuple(json.loads(r.members_json))
        active = mask_for(
            states,
            pat,
            float(r.z_on),
        ).astype(float)

        score += float(r.weight) * active

    return score.clip(0, 1)

# ---------------------------------------------------------------------
# Floor choice over TWO validation years
# ---------------------------------------------------------------------

def choose_floor(
    validation,
    score,
):
    rows = []

    for floor in FLOORS:
        pos = floor + (1.0 - floor) * score

        net, held, turnover = strategy_returns(
            pos,
            validation["daily_ret_clp"],
        )

        u, p = utility(
            net,
            turnover,
        )

        # Year consistency penalty.
        annual = (
            net.groupby(net.index.year)
            .apply(lambda s: (1 + s).prod() - 1)
        )

        neg_year_penalty = float(
            np.abs(annual[annual < 0]).sum()
        )

        adjusted = u - 0.50 * neg_year_penalty

        rows.append({
            "floor": floor,
            "utility": u,
            "adjusted_utility": adjusted,
            "return": p["total_return"],
            "sharpe": p["sharpe"],
            "drawdown": p["max_drawdown"],
            "turnover": float(turnover.sum()),
            "positive_year_rate": float(
                (annual > 0).mean()
            ),
        })

    table = pd.DataFrame(rows).sort_values(
        ["adjusted_utility", "utility"],
        ascending=False,
    )

    return float(table.iloc[0]["floor"]), table

# ---------------------------------------------------------------------
# Evaluate one horizon for one test year
# ---------------------------------------------------------------------

def evaluate_horizon(
    df,
    test_year,
    h,
):
    discovery_years = [
        test_year - 5,
        test_year - 4,
        test_year - 3,
    ]
    validation_years = [
        test_year - 2,
        test_year - 1,
    ]

    required = (
        discovery_years
        + validation_years
        + [test_year]
    )

    if not all(enough_year(df, y) for y in required):
        return None

    discovery = years_df(
        df, discovery_years
    )
    validation = years_df(
        df, validation_years
    )
    test = years_df(
        df, [test_year]
    )

    ft = discover_stable_features(
        df,
        h,
        discovery_years,
    )

    if len(ft) < 6:
        return None

    features = ft["feature"].tolist()
    scaling = scale_fit(
        discovery,
        features,
    )

    states_by_year = {}

    for y in discovery_years + validation_years + [test_year]:
        states_by_year[y] = state_matrix(
            df[df.index.year == y],
            ft,
            scaling,
        )

    discovered = discover_synergies(
        df,
        h,
        discovery_years,
        ft,
        states_by_year,
    )

    validated = validate_synergies(
        df,
        h,
        validation_years,
        discovered,
        states_by_year,
    )

    # Concatenate validation states keeping order.
    val_states = pd.concat(
        [states_by_year[y] for y in validation_years]
    ).sort_index()

    test_states = states_by_year[test_year]

    val_score = confluence_score(
        val_states,
        validated,
    )

    floor, floor_table = choose_floor(
        validation,
        val_score,
    )

    val_pos = (
        floor
        + (1.0 - floor) * val_score
    )

    val_net, _, val_turn = strategy_returns(
        val_pos,
        validation["daily_ret_clp"],
    )
    val_u, val_perf = utility(
        val_net,
        val_turn,
    )

    test_score = confluence_score(
        test_states,
        validated,
    )

    test_pos = (
        floor
        + (1.0 - floor) * test_score
    )

    test_net, held, test_turn = strategy_returns(
        test_pos,
        test["daily_ret_clp"],
    )
    test_u, test_perf = utility(
        test_net,
        test_turn,
    )

    return {
        "horizon": h,
        "feature_table": ft,
        "discovered": discovered,
        "validated": validated,
        "floor": floor,
        "floor_table": floor_table,
        "validation_utility": val_u,
        "validation_perf": val_perf,
        "test_utility": test_u,
        "test_perf": test_perf,
        "test_score": test_score,
        "test_position": held,
        "test_turnover": test_turn,
        "test_ret": test_net,
        "test_frame": test,
    }

# ---------------------------------------------------------------------
# Asset walk-forward
# ---------------------------------------------------------------------

def run_asset(
    asset,
    df,
):
    yearly = []
    patterns = []
    daily = []

    latest = int(df.index.max().year)

    for year in range(FIRST_TEST_YEAR, latest + 1):
        candidates = []

        for h in HORIZONS:
            r = evaluate_horizon(
                df,
                year,
                h,
            )

            if r is not None:
                candidates.append(r)

        if not candidates:
            continue

        # Choose horizon ONLY from two validation years.
        best = max(
            candidates,
            key=lambda x: x["validation_utility"],
        )

        p = best["test_perf"]

        yearly.append({
            "asset": asset,
            "test_year": year,
            "horizon": best["horizon"],
            "floor": best["floor"],
            "validation_utility": best["validation_utility"],
            "validation_return": best["validation_perf"]["total_return"],
            "validation_sharpe": best["validation_perf"]["sharpe"],
            "future_return": p["total_return"],
            "future_sharpe": p["sharpe"],
            "future_drawdown": p["max_drawdown"],
            "future_turnover": float(
                best["test_turnover"].sum()
            ),
            "mean_position": float(
                best["test_position"].mean()
            ),
            "n_features": len(
                best["feature_table"]
            ),
            "n_synergies": len(
                best["validated"]
            ),
        })

        for r in best["validated"].itertuples(index=False):
            patterns.append({
                "asset": asset,
                "test_year": year,
                "horizon": best["horizon"],
                "floor": best["floor"],
                "pattern": r.pattern,
                "size": r.size,
                "z_on": r.z_on,
                "support_discovery": r.support_discovery,
                "positive_year_rate": r.positive_year_rate,
                "edge_discovery": r.edge_discovery,
                "best_single_edge": r.best_single_edge,
                "synergy_edge": r.synergy_edge,
                "support_validation": r.support_validation,
                "edge_validation": r.edge_validation,
                "worst_edge_validation": r.worst_edge_validation,
                "weight": r.weight,
            })

        z = pd.DataFrame(
            index=best["test_frame"].index
        )
        z["asset"] = asset
        z["year"] = year
        z["horizon"] = best["horizon"]
        z["floor"] = best["floor"]
        z["synergy_score"] = best["test_score"]
        z["position"] = best["test_position"]
        z["turnover"] = best["test_turnover"]
        z["strategy_ret"] = best["test_ret"]
        z["daily_ret_clp"] = (
            best["test_frame"]["daily_ret_clp"]
        )
        daily.append(z)

        print(
            f"  {asset} {year}: "
            f"H={best['horizon']} | "
            f"floor={best['floor']:.2f} | "
            f"synergies={len(best['validated'])} | "
            f"futuro={p['total_return']:+.2%} | "
            f"Sharpe={p['sharpe']:.2f}"
        )

    return (
        pd.DataFrame(yearly),
        pd.DataFrame(patterns),
        pd.concat(daily).sort_index()
        if daily else pd.DataFrame(),
    )

# ---------------------------------------------------------------------
# Portfolio common window
# ---------------------------------------------------------------------

def build_portfolio(
    daily,
    frames,
):
    idx = pd.DatetimeIndex(
        sorted(daily.index.unique())
    )

    strategy = pd.Series(
        0.0,
        index=idx,
    )
    benchmark = pd.Series(
        0.0,
        index=idx,
    )

    for asset in TARGETS:
        z = daily[
            daily["asset"] == asset
        ]

        sr = (
            z["strategy_ret"]
            .groupby(z.index)
            .last()
            .reindex(idx)
            .fillna(0.0)
        )

        strategy += (
            MAX_ASSET_WEIGHT * sr
        )

        benchmark += (
            MAX_ASSET_WEIGHT
            * frames[asset]["daily_ret_clp"]
            .reindex(idx)
            .fillna(0.0)
        )

    out = pd.DataFrame(index=idx)
    out["strategy_ret"] = strategy
    out["benchmark_ret"] = benchmark

    out["capital_strategy"] = (
        INITIAL_CAPITAL
        * (1 + strategy).cumprod()
    )

    out["capital_benchmark"] = (
        INITIAL_CAPITAL
        * (1 + benchmark).cumprod()
    )

    return out

def metrics_table(port):
    s = perf(
        port["strategy_ret"]
    )
    b = perf(
        port["benchmark_ret"]
    )

    rows = [
        {
            "name": "SYNERGY_CHALLENGER",
            **s,
        },
        {
            "name": "BENCHMARK_COMMON_WINDOW",
            **b,
        },
    ]

    # Optional v1.7 comparison on same date intersection.
    v17 = ROOT / "mfp3_output_v17" / "portfolio_daily.csv"

    if v17.exists():
        try:
            x = pd.read_csv(
                v17,
                index_col=0,
                parse_dates=True,
            )

            if "portfolio_net_ret" in x:
                common = port.index.intersection(
                    x.index
                )

                if len(common) > 100:
                    m = perf(
                        x.loc[
                            common,
                            "portfolio_net_ret",
                        ]
                    )

                    rows.append({
                        "name": "V17_REFERENCE_COMMON_WINDOW",
                        **m,
                    })
        except Exception:
            pass

    return pd.DataFrame(rows)

# ---------------------------------------------------------------------
# Current research summary
# ---------------------------------------------------------------------

def current_summary(
    yearly,
    patterns,
):
    if yearly.empty:
        return pd.DataFrame()

    latest = int(
        yearly["test_year"].max()
    )
    rows = []

    for asset in TARGETS:
        y = yearly[
            (yearly["asset"] == asset)
            & (yearly["test_year"] == latest)
        ]

        if y.empty:
            continue

        r = y.iloc[-1]

        p = patterns[
            (patterns["asset"] == asset)
            & (patterns["test_year"] == latest)
            & (patterns["horizon"] == r["horizon"])
        ].sort_values(
            "weight",
            ascending=False,
        )

        rows.append({
            "asset": asset,
            "research_year": latest,
            "horizon": int(r["horizon"]),
            "floor": float(r["floor"]),
            "validation_utility": float(
                r["validation_utility"]
            ),
            "historical_future_return": float(
                r["future_return"]
            ),
            "historical_future_sharpe": float(
                r["future_sharpe"]
            ),
            "top_true_synergies": " | ".join(
                f"{x.pattern} [{x.weight:.2f}; "
                f"syn={x.synergy_edge:+.4f}]"
                for x in p.head(5).itertuples()
            ),
        })

    return pd.DataFrame(rows)

# ---------------------------------------------------------------------
# Cadence
# ---------------------------------------------------------------------

def synergy_due(force=False):
    if force or not STATE_JSON.exists():
        return True

    try:
        s = json.loads(
            STATE_JSON.read_text(
                encoding="utf-8"
            )
        )

        last = pd.Timestamp(
            s["last_completed_utc"]
        )

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        now = pd.Timestamp.now(tz="UTC")

        return (
            now - last
        ).days >= RUN_EVERY_DAYS

    except Exception:
        return True

def save_state():
    STATE_JSON.write_text(
        json.dumps(
            {
                "last_completed_utc":
                    now_utc(),
                "version": "v1.13",
            },
            indent=2,
        ),
        encoding="utf-8",
    )

# ---------------------------------------------------------------------
# Lab
# ---------------------------------------------------------------------

def run_synergy_lab():
    ns = get_v112_namespace()

    # v1.12 contains v1.11; use the embedded v1.11 data builders.
    v111 = ns["get_v111_namespace"]()

    print("\n[Synergy] Descargando historia...")
    market = v111["download_history"]()

    frames = {
        asset: v111["build_frame"](
            asset,
            market,
        )
        for asset in TARGETS
    }

    ys = []
    ps = []
    ds = []

    print(
        "\n[Synergy] Nested walk-forward: "
        "3 años discovery + 2 validation + 1 futuro..."
    )

    for asset in TARGETS:
        y, p, d = run_asset(
            asset,
            frames[asset],
        )

        if len(y):
            ys.append(y)
        if len(p):
            ps.append(p)
        if len(d):
            ds.append(d)

    yearly = pd.concat(
        ys,
        ignore_index=True,
    )

    patterns = (
        pd.concat(
            ps,
            ignore_index=True,
        )
        if ps else pd.DataFrame()
    )

    daily = pd.concat(
        ds
    ).sort_index()

    port = build_portfolio(
        daily,
        frames,
    )

    met = metrics_table(
        port
    )

    cur = current_summary(
        yearly,
        patterns,
    )

    yearly.to_csv(
        YEARLY_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    patterns.to_csv(
        PATTERNS_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    port.to_csv(
        PORTFOLIO_CSV,
        encoding="utf-8-sig",
    )

    met.to_csv(
        METRICS_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    cur.to_csv(
        CURRENT_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    save_state()

    print("\n" + "=" * 94)
    print("TRUE SYNERGY DISCOVERY — RESULTADO")
    print("=" * 94)

    with pd.option_context(
        "display.max_columns",
        None,
        "display.width",
        190,
    ):
        print(met)

    print(
        "\nCapital Synergy Challenger:",
        f"${port['capital_strategy'].iloc[-1]:,.0f} CLP"
    )

    print(
        "Capital Benchmark misma ventana:",
        f"${port['capital_benchmark'].iloc[-1]:,.0f} CLP"
    )

    print("\nSinergias actuales:")
    with pd.option_context(
        "display.max_columns",
        None,
        "display.width",
        220,
    ):
        print(cur)

# ---------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser()
    p.add_argument(
        "--synergy",
        action="store_true",
    )
    p.add_argument(
        "--install",
        action="store_true",
    )
    p.add_argument(
        "--uninstall",
        action="store_true",
    )
    p.add_argument(
        "--status",
        action="store_true",
    )
    p.add_argument(
        "--full",
        action="store_true",
    )
    args = p.parse_args()

    if args.install:
        install_this_file()
        return

    if args.uninstall:
        uninstall_this_file()
        return

    if args.status:
        print("\nMFP-3 v1.13 STATUS")
        print("Synergy Lab:", LAB.resolve())
        print(
            "Synergy due:",
            synergy_due(False),
        )
        print(
            "Metrics:",
            METRICS_CSV.exists(),
        )
        print(
            "Patterns:",
            PATTERNS_CSV.exists(),
        )
        return

    print("\n" + "=" * 96)
    print("MFP-3 ONE FILE v1.13 — SYNERGY DISCOVERY ENGINE")
    print("=" * 96)

    run_v112(args)

    if synergy_due(args.synergy):
        print(
            "\n[v1.13] Buscando sinergias históricas verdaderas. "
            "Puede tardar varios minutos..."
        )
        run_synergy_lab()
    else:
        print(
            "\n[v1.13] Synergy Lab ya está actualizado. "
            "Se repite automáticamente cada 21 días."
        )

    print(
        "\nSynergy Engine sigue siendo Challenger. "
        "v1.7-FROZEN permanece intacta."
    )

if __name__ == "__main__":
    main()
